SELECT tblInspektionsbericht.[Element Nr], tblInspektionsbericht.Inspektionsgrund, tblInspektionsbericht.BlisterAnodenflaeche, tblInspektionsbericht.BlisterPeripherieOben, tblInspektionsbericht.BlisterPeripherieUnten, tblInspektionsbericht.BlisterPeripherieSeite, tblInspektionsbericht.BlisterEcken, tblInspektionsbericht.Falten, tblInspektionsbericht.Druckstellen, tblInspektionsbericht.SichtbareLoecher, tblInspektionsbericht.Risse, tblInspektionsbericht.BlisterBemerkungen, tblInspektionsbericht.ProbeKathode, tblInspektionsbericht.ProbeAnode, tblInspektionsbericht.ProbeMembran, tblInspektionsbericht.EinsteckrohrAnodeOK, tblInspektionsbericht.EinsteckrohrAnodeBemerkung, tblInspektionsbericht.EinsteckrohrKathodeOK, tblInspektionsbericht.EinsteckrohrKathodeBemerkung, tblInspektionsbericht.DistanzsteifenAnodeOK, tblInspektionsbericht.DistanzstreifenAnodeBemerkung, tblInspektionsbericht.DistanzstreifenKathodeOK, tblInspektionsbericht.DistanzstreifenKathodeBemerkung, tblInspektionsbericht.RahmendichtungOK, tblInspektionsbericht.RahmendichtungBemerkung, tblInspektionsbericht.Name, tblInspektionsbericht.Date, tblInspektionsbericht.BemerkungenInspektionsbericht
FROM tblInspektionsbericht
WHERE (((tblInspektionsbericht.[Element Nr])=(Select [Element Nr] FROM tblGewElementInspektionsbericht)));
